class MarketMakingStrategy_EMERALDS:
    MAX_INVENTORY       = 76
    QUOTE_SIZE          = 8
    PASSIVE_SPREAD      = 7.79053
    INV_SKEW            = 0.0434
    TAKE_SPREAD         = 2.0
    QUOTE_INNER_OFFSET  = 1   # None → use PASSIVE_SPREAD; int → use bid+offset/ask-offset
    QUOTE_FILTER_THRESH = 0.0  # 0 = disabled; >0 → suppress one side on momentum

    def run(self, state: "TradingState", ctx: dict) -> "list[Order]":
        from datamodel import Order
        orders = []
        od = state.order_depths.get("EMERALDS")
        if od is None:
            return orders

        best_ask = min(od.sell_orders.keys()) if od.sell_orders else None
        best_bid = max(od.buy_orders.keys())  if od.buy_orders  else None
        if best_ask is None or best_bid is None:
            return orders

        position = state.position.get("EMERALDS", 0)
        mid      = (best_bid + best_ask) / 2.0

        # Inventory-skewed fair value: shifts quotes against accumulated position
        # to attract offsetting flow and limit adverse selection
        fair_adj = mid - (position / max(self.MAX_INVENTORY, 1)) * self.INV_SKEW

        # Take layer: cross market quotes when they are mispriced vs fair_adj
        if best_ask < fair_adj - self.TAKE_SPREAD and position < self.MAX_INVENTORY:
            orders.append(Order("EMERALDS", best_ask,  1))
        if best_bid > fair_adj + self.TAKE_SPREAD and position > -self.MAX_INVENTORY:
            orders.append(Order("EMERALDS", best_bid, -1))

        # Make layer: passive limit orders
        if self.QUOTE_INNER_OFFSET is not None:
            buy_price  = best_bid + self.QUOTE_INNER_OFFSET
            sell_price = best_ask - self.QUOTE_INNER_OFFSET
        else:
            buy_price  = int(fair_adj - self.PASSIVE_SPREAD)
            sell_price = int(fair_adj + self.PASSIVE_SPREAD)

        if buy_price >= sell_price:
            return orders

        # Directional quoting filter: suppress one side when lag1_return exceeds threshold
        _prev_key  = "prev_mid_EMERALDS"
        _prev_mid  = ctx.get(_prev_key, float("nan"))
        _lag1      = (mid - _prev_mid) if (_prev_mid == _prev_mid) else 0.0
        ctx[_prev_key] = mid
        _suppress_buy  = self.QUOTE_FILTER_THRESH > 0 and _lag1 < -self.QUOTE_FILTER_THRESH
        _suppress_sell = self.QUOTE_FILTER_THRESH > 0 and _lag1 >  self.QUOTE_FILTER_THRESH

        if position < self.MAX_INVENTORY and not _suppress_buy:
            orders.append(Order("EMERALDS", buy_price,  self.QUOTE_SIZE))
        if position > -self.MAX_INVENTORY and not _suppress_sell:
            orders.append(Order("EMERALDS", sell_price, -self.QUOTE_SIZE))
        return orders


